<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Conversations extends MY_Controller {
 private $c;public function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c){$this->output->_display();exit;}$this->load->model('Conversation_model','conversations');}
 public function index(){if($this->input->method(TRUE)==='POST')return $this->create();$page=max(1,(int)($this->input->get('page')?:1));$per=min(100,max(1,(int)($this->input->get('perPage')?:20)));$q=array('archived'=>$this->input->get('archived')==='true','pinned'=>$this->input->get('pinned')==='true','search'=>substr((string)$this->input->get('q'),0,200));list($items,$total)=$this->conversations->all($this->c['sub'],$this->c['organizationId'],$q,$page,$per);return $this->respond(array('items'=>$items,'pagination'=>array('page'=>$page,'perPage'=>$per,'total'=>$total,'totalPages'=>(int)ceil($total/$per))));}
 public function conversation($id){$method=$this->input->method(TRUE);if($method==='GET'){$r=$this->conversations->get($id,$this->c['sub'],$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Conversation not found',404);}if($method==='DELETE'){if(!$this->conversations->soft_delete($id,$this->c['sub'],$this->c['organizationId']))return $this->fail('NOT_FOUND','Conversation not found',404);return $this->respond(array('ok'=>TRUE));}$d=$this->body();if(isset($d['title'])&&(trim($d['title'])===''||strlen($d['title'])>200))return $this->fail('VALIDATION_ERROR','Invalid title',422);foreach(array('pinned','isArchived') as $f)if(isset($d[$f])&&!is_bool($d[$f]))return $this->fail('VALIDATION_ERROR','Invalid '.$f,422);$r=$this->conversations->update_owned($id,$this->c['sub'],$this->c['organizationId'],$d);return $r?$this->respond($r):$this->fail('NOT_FOUND','Conversation not found',404);}
 public function messages($id){if($this->input->method(TRUE)==='POST')return $this->send($id);$page=max(1,(int)($this->input->get('page')?:1));$per=min(100,max(1,(int)($this->input->get('perPage')?:100)));$r=$this->conversations->messages($id,$this->c['sub'],$this->c['organizationId'],$page,$per);return $r?$this->respond($r):$this->fail('NOT_FOUND','Conversation not found',404);}
 private function create(){$d=$this->body();$d['title']=$d['title']??'New conversation';if(trim($d['title'])===''||strlen($d['title'])>200||isset($d['firstMessage'])&&strlen($d['firstMessage'])>10000)return $this->fail('VALIDATION_ERROR','Invalid conversation input',422);$this->load->model('Workspace_model','workspaces');list(,$ws)=$this->workspaces->context($this->c['sub'],$this->c['organizationId']);return $this->respond($this->conversations->create($this->c['sub'],$this->c['organizationId'],$ws['id']??NULL,$d),201);}
 private function send($id){$d=$this->body();$content=trim($d['content']??'');if($content===''||strlen($content)>20000)return $this->fail('VALIDATION_ERROR','Message must contain 1–20000 characters',422);$attachmentIds=$d['attachmentIds']??array();$this->db->trans_begin();$m=$this->conversations->send_user($id,$this->c['sub'],$this->c['organizationId'],$content,$d['parentId']??NULL);if($m===NULL){$this->db->trans_rollback();return $this->fail('NOT_FOUND','Conversation not found',404);}if($m===FALSE){$this->db->trans_rollback();return $this->fail('VALIDATION_ERROR','Parent message does not belong to this conversation',422);}$this->load->model('Attachment_model','attachments');list($claimed,$claimError)=$this->attachments->claim($attachmentIds,$this->c['organizationId'],$this->c['sub'],$id,$m['id']);if(!$claimed){$this->db->trans_rollback();return $this->fail('VALIDATION_ERROR',$claimError,422);}$this->db->trans_commit();$m=$this->conversations->message_view($this->db->where('id',$m['id'])->get('messages')->row_array());$history=$this->conversations->ai_history($id,$this->c['sub'],$this->c['organizationId']);$this->load->library('Ai_provider');$result=$this->ai_provider->complete($history,$d['modelId']??NULL);$sse=strpos((string)$this->input->get_request_header('Accept'),'text/event-stream')!==FALSE;if(!$result['ok']){if($sse){$this->output->set_content_type('text/event-stream')->set_header('Cache-Control: no-cache, no-transform')->set_output("event: message.created\ndata: ".json_encode($m)."\n\nevent: message.error\ndata: ".json_encode(array('error'=>array('code'=>$result['code'],'message'=>$result['message'])))."\n\n");return;}return $this->fail($result['code'],$result['message'],503,array('message'=>$m));}$assistant=$this->conversations->assistant($id,$result['content'],$result['model'],$result);$this->load->model('Ai_monitoring_model','monitoring');$this->monitoring->record(array('organization_id'=>$this->c['organizationId'],'user_id'=>$this->c['sub'],'channel'=>'chat','provider'=>'openai','model_id'=>$result['model'],'feature'=>'chat','duration_ms'=>$result['durationMs'],'prompt_tokens'=>$result['tokensIn'],'completion_tokens'=>$result['tokensOut'],'status'=>'succeeded','error'=>NULL));if($sse){$this->output->set_content_type('text/event-stream')->set_header('Cache-Control: no-cache, no-transform')->set_output("event: message.created\ndata: ".json_encode($m)."\n\nevent: message.created\ndata: ".json_encode(array('id'=>$assistant['id'],'role'=>'assistant','modelId'=>$assistant['modelId'],'status'=>'completed'))."\n\nevent: message.delta\ndata: ".json_encode(array('id'=>$assistant['id'],'delta'=>$assistant['content']))."\n\nevent: message.done\ndata: ".json_encode(array('id'=>$assistant['id'],'content'=>$assistant['content'],'usage'=>array('tokensIn'=>$result['tokensIn'],'tokensOut'=>$result['tokensOut'],'costMicros'=>0)))."\n\n");return;}return $this->respond(array('id'=>$assistant['id'],'content'=>$assistant['content'],'modelId'=>$assistant['modelId'],'usage'=>array('tokensIn'=>$result['tokensIn'],'tokensOut'=>$result['tokensOut'],'costMicros'=>0)));}

 public function rename($id){$d=$this->body();$title=trim($d['title']??'');if($title===''||strlen($title)>200)return $this->fail('VALIDATION_ERROR','Title must contain 1–200 characters',422);$r=$this->conversations->rename($id,$this->c['sub'],$this->c['organizationId'],$title);if(!$r)return $this->fail('NOT_FOUND','Conversation not found',404);$this->audit_change('conversation.renamed',$id);return $this->respond($r);}
 public function pin($id){$pinned=$this->input->method(TRUE)!=='DELETE';$r=$this->conversations->set_pin($id,$this->c['sub'],$this->c['organizationId'],$pinned);if(!$r)return $this->fail('NOT_FOUND','Conversation not found',404);$this->audit_change($pinned?'conversation.pinned':'conversation.unpinned',$id);return $this->respond($r);}
 public function archive($id){$r=$this->conversations->set_archive($id,$this->c['sub'],$this->c['organizationId'],TRUE);if(!$r)return $this->fail('NOT_FOUND','Conversation not found',404);$this->audit_change('conversation.archived',$id);return $this->respond($r);}
 public function unarchive($id){$r=$this->conversations->set_archive($id,$this->c['sub'],$this->c['organizationId'],FALSE);if(!$r)return $this->fail('NOT_FOUND','Conversation not found',404);$this->audit_change('conversation.unarchived',$id);return $this->respond($r);}
 public function permanent($id){if($this->input->method(TRUE)!=='DELETE')return $this->fail('METHOD_NOT_ALLOWED','DELETE required',405);if(!$this->conversations->purge($id,$this->c['sub'],$this->c['organizationId']))return $this->fail('NOT_FOUND','Conversation not found or creator access required',404);$this->audit_change('conversation.deleted_permanently',$id);return $this->respond(array('deleted'=>TRUE,'id'=>$id,'permanent'=>TRUE));}
 private function audit_change($type,$id){$this->db->insert('audit_events',array('organization_id'=>$this->c['organizationId'],'user_id'=>$this->c['sub'],'event_type'=>$type,'payload'=>json_encode(array('resourceType'=>'conversation','resourceId'=>$id)),'ip_address'=>$this->input->ip_address(),'user_agent'=>substr((string)$this->input->user_agent(),0,500),'created_at'=>date('Y-m-d H:i:s')));}

 public function shares($id){$this->load->model('Share_model','shares');if($this->input->method(TRUE)==='POST'){$d=$this->body();$d+=array('access'=>'anyone_with_link','permissions'=>'view','allowed'=>array());$err=$this->share_valid($d,TRUE);if($err)return $this->fail('VALIDATION_ERROR',$err,422);$r=$this->shares->create($id,$this->c['sub'],$this->c['organizationId'],$d);return $r?$this->respond($r,201):$this->fail('NOT_FOUND','Conversation not found',404);} $r=$this->shares->all($id,$this->c['sub'],$this->c['organizationId']);return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Conversation not found',404);}
 public function share($id,$sid){$this->load->model('Share_model','shares');if($this->input->method(TRUE)==='DELETE'){if(!$this->shares->delete_share($id,$sid,$this->c['sub'],$this->c['organizationId']))return $this->fail('NOT_FOUND','Share not found',404);return $this->respond(array('deleted'=>TRUE,'id'=>$sid));}$d=$this->body();$err=$this->share_valid($d,FALSE);if($err)return $this->fail('VALIDATION_ERROR',$err,422);$r=$this->shares->mutate($id,$sid,$this->c['sub'],$this->c['organizationId'],$d);return $r?$this->respond($r):$this->fail('NOT_FOUND','Share not found',404);}
 public function share_enable($id,$sid){$this->load->model('Share_model','shares');$r=$this->shares->mutate($id,$sid,$this->c['sub'],$this->c['organizationId'],array('_enabled'=>TRUE));return $r?$this->respond($r):$this->fail('NOT_FOUND','Share not found',404);}
 public function share_disable($id,$sid){$this->load->model('Share_model','shares');$r=$this->shares->mutate($id,$sid,$this->c['sub'],$this->c['organizationId'],array('_enabled'=>FALSE));return $r?$this->respond($r):$this->fail('NOT_FOUND','Share not found',404);}
 public function share_access($id,$sid){$this->load->model('Share_model','shares');$r=$this->shares->logs($id,$sid,$this->c['sub'],$this->c['organizationId']);return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Share not found',404);}
 private function share_valid($d,$create){if(isset($d['access'])&&!in_array($d['access'],array('anyone_with_link','organization','restricted','specific'),TRUE))return 'Invalid access mode';if(isset($d['permissions'])&&!in_array($d['permissions'],array('view','comment','edit'),TRUE))return 'Invalid permissions';if(isset($d['allowed'])&&(!is_array($d['allowed'])||count($d['allowed'])>100))return 'Allowed list is invalid';if(isset($d['password'])&&$d['password']!==NULL&&(strlen($d['password'])<4||strlen($d['password'])>128))return 'Password must contain 4–128 characters';if(isset($d['expiresAt'])&&$d['expiresAt']!==NULL&&strtotime($d['expiresAt'])===FALSE)return 'Invalid expiration timestamp';return NULL;}

 public function participants($id){$this->load->model('Conversation_ops_model','ops');if($this->input->method(TRUE)==='POST'){list($r,$e)=$this->ops->add($id,$this->c['sub'],$this->c['organizationId'],$this->body());if($r)return $this->respond($r,201);$messages=array('conversation'=>'Conversation not found','choice'=>'Provide exactly one userId or agentId','member'=>'User is not a member of this organization','duplicate'=>'User is already a participant','agent'=>'Agent not found');return $this->fail($e==='duplicate'?'CONFLICT':'VALIDATION_ERROR',$messages[$e],$e==='duplicate'?409:422);} $r=$this->ops->participants($id,$this->c['sub'],$this->c['organizationId']);return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Conversation not found',404);}
 public function participant($id,$pid){if($this->input->method(TRUE)!=='DELETE')return $this->fail('METHOD_NOT_ALLOWED','DELETE required',405);$this->load->model('Conversation_ops_model','ops');$e=$this->ops->remove($id,$pid,$this->c['sub'],$this->c['organizationId']);if(!$e)return $this->respond(array('removed'=>TRUE,'id'=>$pid));return $this->fail($e==='creator'?'CONFLICT':'NOT_FOUND',$e==='creator'?'The conversation creator cannot be removed from their own conversation':'Participant not found',$e==='creator'?409:404);}
 public function read_state($id){$this->load->model('Conversation_ops_model','ops');$r=$this->ops->read_state($id,$this->c['sub'],$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Conversation not found',404);}
 public function mark_read($id){$d=$this->body();$at=!empty($d['at'])?strtotime($d['at']):time();if($at===FALSE||$at>time())return $this->fail('VALIDATION_ERROR','Read timestamp is invalid or in the future',422);$this->load->model('Conversation_ops_model','ops');$r=$this->ops->read_state($id,$this->c['sub'],$this->c['organizationId'],date('Y-m-d H:i:s',$at));return $r?$this->respond($r):$this->fail('NOT_FOUND','Conversation not found',404);}
 public function stats($id){$this->load->model('Conversation_ops_model','ops');$r=$this->ops->stats($id,$this->c['sub'],$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Conversation not found',404);}
 public function transcript($id){$this->load->model('Conversation_ops_model','ops');$r=$this->ops->transcript($id,$this->c['sub'],$this->c['organizationId'],$this->input->get('includeSystem')!=='false');if(!$r)return $this->fail('NOT_FOUND','Conversation not found',404);if($this->input->get('format')==='markdown'){$md='# '.$r['title']."\n\n";foreach($r['entries'] as $e)$md.='## '.ucfirst($e['role'])."\n\n".$e['content']."\n\n";$r['format']='markdown';$r['content']=$md;}else $r['format']='json';return $this->respond($r);}
 public function restore($id){$this->load->model('Conversation_ops_model','ops');$r=$this->ops->restore($id,$this->c['sub'],$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Deleted conversation not found',404);}
 public function message($id,$mid){$this->load->model('Conversation_ops_model','ops');$method=$this->input->method(TRUE);if($method==='PATCH'){$content=trim($this->body()['content']??'');if($content==='')return $this->fail('VALIDATION_ERROR','Content is required',422);$r=$this->ops->edit_message($id,$mid,$this->c['sub'],$this->c['organizationId'],$content);}elseif($method==='DELETE'){$r=$this->ops->redact_message($id,$mid,$this->c['sub'],$this->c['organizationId'],$this->body()['reason']??NULL);}else $r=$this->ops->message($id,$mid,$this->c['sub'],$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Message not found or operation not permitted',404);}
 public function search(){ $q=trim((string)$this->input->get('q'));if(strlen($q)<2)return $this->fail('VALIDATION_ERROR','Search query must contain at least 2 characters',422);$page=max(1,(int)$this->input->get('page'));$per=min(100,max(1,(int)($this->input->get('perPage')?:20)));$role=$this->input->get('role');if($role&&!in_array($role,array('user','assistant','system','tool'),TRUE))return $this->fail('VALIDATION_ERROR','Invalid message role',422);$this->load->model('Conversation_ops_model','ops');return $this->respond($this->ops->search($this->c['sub'],$this->c['organizationId'],$q,$this->input->get('conversationId'),$role,$page,$per));}
 public function unread(){ $this->load->model('Conversation_ops_model','ops');return $this->respond($this->ops->unread($this->c['sub'],$this->c['organizationId'],min(100,max(1,(int)($this->input->get('limit')?:50)))));}
 public function deleted(){ $page=max(1,(int)$this->input->get('page'));$per=min(100,max(1,(int)($this->input->get('perPage')?:20)));$this->load->model('Conversation_ops_model','ops');return $this->respond($this->ops->deleted($this->c['sub'],$this->c['organizationId'],$page,$per));}
 public function digest($id){$max=min(20,max(1,(int)($this->input->get('maxKeywords')?:8)));$this->load->model('Conversation_ops_model','ops');$r=$this->ops->digest($id,$this->c['sub'],$this->c['organizationId'],$max);return $r?$this->respond($r):$this->fail('NOT_FOUND','Conversation not found',404);}
}
